const imgs = [...document.querySelectorAll('svg image')];
const info = imgs.map(i => ({href: (i.getAttribute('href')||'').slice(0,20), nw: i.naturalWidth || 0}));
return {title: document.title, svgEls: document.querySelectorAll('svg *').length, pngIcons: imgs.filter(i=>(i.getAttribute('href')||'').startsWith('data:image/png')).length, svgIcons: imgs.filter(i=>(i.getAttribute('href')||'').startsWith('data:image/svg')).length, imgs: info.slice(0,10)};
